export function assertRecoveryPackageMembers(actual,expected){for(const rows of [actual,expected])assert.equal(new Set(rows.map(r=>r.path)).size,rows.length,'duplicate installed member path');const ordered=rows=>rows.map(({path,bytes,sha256})=>({path,bytes,sha256})).sort((a,b)=>a.path<b.path?-1:a.path>b.path?1:0);assert.deepEqual(ordered(actual),ordered(expected),'complete installed package member identity');}
export const RECOVERY_METHOD=Object.freeze({kind:'rx9006-recovery-v1',normalOwners:2,diagnosticOwners:1,contexts:204,budgetMs:10800000,perContextWatchdogMs:300000,priorReceiver:PRIOR_RECORD,tailEstimates:false});
export function recoveryPlan(){const jobs=[];for(let owner=0;owner<3;owner++)for(const deadline of owner%2?['explicit60s','default30s']:['default30s','explicit60s'])for(const size of [1000,10000])for(const host of ['Node-direct','browser-direct','browser-real-module-worker'])for(const variant of ['source','positions-offsets'])for(const role of owner%2?['current','acceptedN9','preN9']:['preN9','acceptedN9','current']){if(size===10000&&role==='acceptedN9')continue;jobs.push({family:'adversarial',size,host,variant,role,deadline,deadlineOptions:deadline==='default30s'?{}:{deadlineMs:60000},owner,mode:owner<2?'normal':'diagnostic',control:false});}for(let owner=0;owner<3;owner++)for(const deadline of owner%2?['explicit60s','default30s']:['default30s','explicit60s'])for(const family of ['real-docs','high-cardinality'])for(const role of owner%2?['current','preN9']:['preN9','current'])jobs.push({family,size:10000,host:'Node-direct',variant:'source',role,deadline,deadlineOptions:deadline==='default30s'?{}:{deadlineMs:60000},owner,mode:owner<2?'normal':'diagnostic',control:true});assert.equal(jobs.length,204);return jobs.map((job,index)=>({...job,index,key:[index,job.family,job.size,job.host,job.variant,job.role,job.deadline,job.owner,job.mode].join('-')}));}
const frozenIdentities=new Map();function frozenIdentity(family,size){const key=family+'-'+size;if(!frozenIdentities.has(key))frozenIdentities.set(key,verifyFrozen(workloadFor(family,size)).identity);return frozenIdentities.get(key);}
export function validateRecoveryRow(row,job,context){const advertisesProfile=Object.hasOwn(row,'profilingRevision')||Boolean(context&&Object.hasOwn(context,'profilingRevision'))||Boolean(row.exercise&&Object.hasOwn(row.exercise,'phaseProfile'))||Boolean(job.mode==='diagnostic'&&(Object.hasOwn(row,'verificationRevision')||row.exercise&&Object.hasOwn(row.exercise,'verificationRevision')));assert.equal(Object.hasOwn(row.exercise??{},'phaseProfileError'),false,'collected profile error');for(const field of ['phaseProfile','phaseProfileError'])assert.equal(Object.hasOwn(row,field),false,'profile at wrong row level');assert.equal(Object.hasOwn(row.exercise??{},'profilingRevision'),false,'profile revision at wrong exercise level');for(const operation of [...(row.exercise?.samples??[]),...(row.exercise?.observations??[])])for(const field of ['phaseProfile','profilingRevision','phaseProfileError'])assert.equal(Object.hasOwn(operation,field),false,'operation profile leakage');if(advertisesProfile){assert.deepEqual(row.profilingRevision,RECOVERY_PROFILE_REVISION,'profiling revision');if(context&&Object.hasOwn(context,'profilingRevision'))assert.deepEqual(context.profilingRevision,RECOVERY_PROFILE_REVISION,'context profiling revision');if(job.mode==='diagnostic')validateRecoveryProfile(row.exercise?.phaseProfile,{realm:job.host==='Node-direct'?'node-main':'browser-main'});}if(job.mode==='normal')assert.equal(Object.hasOwn(row.exercise??{},'phaseProfile'),false,'normal phase observer leakage');const advertisesRevision=Object.hasOwn(row,'verificationRevision')||Boolean(row.exercise&&Object.hasOwn(row.exercise,'verificationRevision'))||Boolean(context&&Object.hasOwn(context,'verificationRevision'));if(advertisesRevision){assertRecoveryVerificationRevision(row.verificationRevision);assertRecoveryVerificationRevision(row.exercise?.verificationRevision);if(context&&Object.hasOwn(context,'verificationRevision')){assertRecoveryVerificationRevision(context.verificationRevision);assert.deepEqual(row.verificationRevision,context.verificationRevision,'row verification revision');assert.deepEqual(row.exercise.verificationRevision,context.verificationRevision,'exercise verification revision');}}if(context){for(const key of ['artifactSha256','preparedSha256','identity'])assert.deepEqual(row[key],context[key],'row binding '+key);}assert.deepEqual(row.identity??frozenIdentity(job.family,job.size),frozenIdentity(job.family,job.size),'frozen workload identity');assert.deepEqual(row.job,job,'job identity');assert.equal(row.outcome,'Collected');assert.equal(row.exercise.outcome,'Collected');assert.deepEqual(row.exercise.priorRecord,PRIOR_RECORD);assert.deepEqual(row.exercise.deadlineOptions,job.deadlineOptions);const operations=job.mode==='normal'?row.exercise.samples:row.exercise.observations;assert.equal((job.mode==='normal'?row.exercise.observations:row.exercise.samples).length,0);assert.deepEqual(operations.map(x=>x.operation),['build','exportSource','restoreSource','deadlineRestore','abortedRestore']);for(const op of operations){assert.ok(['Pass','Refused','Cancelled','Unknown','Not run'].includes(op.outcome),'unexpected outcome');if(op.outcome==='Not run'){assert.equal(op.attempts,0);assert.ok(typeof op.reason==='string'&&op.reason);assert.ok(['Refused','Cancelled','Unknown'].includes(op.dependencyOutcome),'not-run dependency outcome');for(const field of ['wallMs','invocationToReturnMs','returnToSettlementMs','cpuUserMs','cpuSystemMs','processSamples','result','error','counters'])assert.equal(op[field],undefined,'not-run fabricated observation');continue;}assert.equal(op.attempts,1);assert.ok([op.wallMs,op.invocationToReturnMs,op.returnToSettlementMs].every(v=>Number.isFinite(v)&&v>=0),'finite timing components');assert.ok(Math.abs(op.wallMs-op.invocationToReturnMs-op.returnToSettlementMs)<1e-6,'timing boundary sum');assert.deepEqual(op.deadlineOptions,op.operation==='deadlineRestore'?{deadlineMs:1}:job.deadlineOptions);assert.equal(Boolean(op.counters),job.mode==='diagnostic');if(job.host!=='Node-direct'){assert.equal(op.cpuUserMs,undefined,'browser CPU fabricated');assert.equal(op.cpuSystemMs,undefined,'browser CPU fabricated');}else if(context)assert.ok([op.cpuUserMs,op.cpuSystemMs].every(v=>Number.isFinite(v)&&v>=0),'Node CPU actual samples');if(op.counters)for(const key of ['emittedSteps','emittedWorkUnits','hostYields','continuationsScheduled'])assert.ok(Number.isSafeInteger(op.counters[key])&&op.counters[key]>=0,'diagnostic counter '+key);if(op.outcome!=='Pass'){assert.equal(recoveryOutcome(op.error),op.outcome);if(op.outcome==='Unknown'){assert.notEqual(op.oldSourceBytesPreserved,true);assert.notEqual(op.oldRemoved,true);}else if(['restoreSource','deadlineRestore','abortedRestore'].includes(op.operation)){assert.equal(op.oldSourceBytesPreserved,true);assert.equal(op.oldQueriesPreserved,true);assert.equal(op.laterWrite?.outcome,'Pass');}}else if(['restoreSource','deadlineRestore','abortedRestore'].includes(op.operation)){assert.equal(op.oldRemoved,true);assert.equal(op.completeSource?.outcome,'Pass');assert.equal(op.completeSource.records,job.size);assert.equal(op.laterWrite?.outcome,'Pass');if(job.mode==='diagnostic')assert.equal(op.completeRootParity,true);}}if(operations[0].outcome!=='Pass')assert.ok(operations.slice(1).every(x=>x.outcome==='Not run'));else{const exported=operations[1];assert.equal(operations.slice(2).every(x=>x.outcome==='Not run'),exported.outcome!=='Pass');}return operations;}
export function validateRecoveryRows(rows,jobs=recoveryPlan(),contextFor){assert.equal(rows.length,jobs.length,'missing/extra contexts');const nodeRows=rows.filter(r=>r.job.host==='Node-direct');if(contextFor){assert.ok(nodeRows.every(r=>Number.isSafeInteger(r.pid)&&r.pid>0),'fresh native process id');assert.equal(new Set(nodeRows.map(r=>r.pid)).size,nodeRows.length,'fresh process per Node context');}const seen=new Set();for(const row of rows){assert.ok(!seen.has(row.job.key),'duplicate context');seen.add(row.job.key);const job=jobs.find(j=>j.key===row.job.key);assert.ok(job,'unexpected context');validateRecoveryRow(row,job,contextFor?.(job));}return {outcome:'Pass',contexts:rows.length,operations:rows.flatMap(row=>validateRecoveryRow(row,row.job)).length};}
