async function namedBrowserContext({browser,server,pkg,job,config,work,output,file,timeout,preparedSha256}){
 let context,timer,artifact=0,primaryError;const pageErrors=[],externalRequests=[],origin='http://127.0.0.1:'+server.address().port;
 const workPromise=(async()=>{context=await browser.newContext();const page=await context.newPage();page.on('pageerror',error=>pageErrors.push(error.message));page.on('request',request=>{if(!request.url().startsWith(origin+'/'))externalRequests.push(request.url());});await page.exposeFunction('persistRecovery',async(value,meta,type)=>{const bytes=type==='state'?JSON.stringify(value):value,name=job.key+'-'+String(artifact++).padStart(2,'0')+'-'+meta.label+'.'+type+'.json';await writeFile(join(output,name),bytes);return {artifact:name,sha256:sha(bytes),bytes:Buffer.byteLength(bytes)};});await page.goto(origin+'/'+job.role+'-'+job.mode+'/index.html',{timeout:Math.min(30000,timeout)});await page.waitForFunction(()=>typeof window.recoveryExercise==='function');const exercise=await page.evaluate(value=>window.recoveryExercise(value),config),row={kind:'rx9006-browser-recovery-row-v1',job,verificationRevision:RECOVERY_VERIFICATION_REVISION,profilingRevision:RECOVERY_PROFILE_REVISION,artifactSha256:pkg.artifactSha256,preparedSha256,identity:work.identity,browserVersion:browser.version(),pageErrors,externalRequests,exercise,outcome:exercise.outcome==='Collected'?'Collected':'Fail'};await save(file,row);assert.deepEqual(pageErrors,[]);assert.deepEqual(externalRequests,[]);return row;})();
 try{return await Promise.race([workPromise,new Promise((_,no)=>{timer=setTimeout(()=>no(Error('Absolute named context watchdog; native outcome unobserved')),timeout);})]);}catch(error){primaryError=error;try{await stageBound(()=>save(join(output,job.key+'.failure.json'),{kind:'rx9006-named-context-orchestration-failure-v1',job,outcome:'Fail',nativeOutcome:null,error:{name:error.name,message:error.message},pageErrors,externalRequests}),3000,'context failure report');}catch(artifactError){try{error.failureArtifactError={name:artifactError.name,message:artifactError.message};}catch{}}throw error;}finally{clearTimeout(timer);workPromise.catch(()=>{});if(context)try{await stageBound(()=>context.close(),3000,'context close');}catch(error){if(!primaryError)throw error;}}
}
// Called only by the dedicated IPC child, never by a collect CLI shortcut.
export async function runNamedRecoveryController(config,supervision){
 assertRecoveryNamedEnvironment();const control=await import('./host-recovery-supervisor.mjs'),{binding,authorization}=config,policy=assertRecoveryRunPolicy(binding.policy),directory=join(supervision.output,'inner'),started=performance.now(),elapsed=()=>supervision.elapsedMs+performance.now()-started;
 assert.equal(supervision.output,binding.output);assert.equal(supervision.bindingSha256,sha(binding),'supervisor exact binding');const report={kind:'rx9006-named-recovery-collection-v1',startedAt:new Date().toISOString(),runPolicy:policy,policyRevision:RECOVERY_RUN_POLICY_REVISION,binding,authorization,authorizationSha256:authorization.sha256,supervisorBinding:{attemptId:supervision.attemptId,bindingSha256:supervision.bindingSha256},method:RECOVERY_METHOD,verificationRevision:RECOVERY_VERIFICATION_REVISION,profilingRevision:RECOVERY_PROFILE_REVISION,planned:policy.contexts,runs:[],outcome:'Running',acceptedPerformanceEvidence:false,interrupted:false,budgetExceeded:false,nativeOutcome:null};let browser,browserServer,server,firstError,sealed;
 const authorize=async()=>{const bytes=await readFile(authorization.path);assert.equal(sha(bytes),authorization.sha256,'authorization changed');return validateRecoveryAuthorization(JSON.parse(bytes),binding);};
 const closingBound=maximum=>Math.max(1,Math.min(maximum,supervision.deadlineEpochMs-Date.now()-6000));
 try{await authorize();sealed=await readNamedPreparation(binding.prepared.path);assert.deepEqual(namedBinding(sealed,binding.output,binding.preflight),binding,'controller binding');const prepared=sealed.prepared,jobs=recoveryPolicyJobs(prepared.jobs,policy);if(policy.phase==='full'){const gate=await readPassingPreflight(binding.preflight.path,sealed,binding.output);assert.equal(gate.sha256,binding.preflight.sha256);assert.equal(gate.supervisorSha256,binding.preflight.supervisorSha256);report.preflight={outcome:'Pass',...binding.preflight};}
 await save(join(directory,'progress.json'),report);
 if(jobs.some(job=>job.host!=='Node-direct')){server=createServer(async(req,res)=>{const match=/^\/([A-Za-z0-9-]+)\/(index\.html|app\.mjs|worker\.mjs)$/.exec(new URL(req.url,'http://localhost').pathname);if(!match||!prepared.packages[match[1]]){res.writeHead(404).end();return;}try{res.setHeader('content-type',match[2].endsWith('.html')?'text/html':'text/javascript');res.setHeader('content-security-policy',"default-src 'self'; script-src 'self'; worker-src 'self'; connect-src 'self'; object-src 'none'");res.end(await readFile(join(prepared.packages[match[1]].directory,match[2])));}catch{res.writeHead(500).end();}});await new Promise((yes,no)=>{server.once('error',no);server.listen(0,'127.0.0.1',yes);});const executable=prepared.executables.chromium,wrapper=await control.createSupervisedBrowserLauncher({executablePath:executable.path,executableSha256:executable.sha256,output:binding.output});browserServer=await chromium.launchServer({headless:true,executablePath:wrapper});browser=await chromium.connect(browserServer.wsEndpoint());assert.equal(browser.version(),'149.0.7827.55','frozen browser version');report.browserVersion=browser.version();report.browserStartupRecipe='Supervisor-owned acknowledged wrapper group, pinned Chromium launchServer and browser connection; outside selected operation windows.';}
 for(const job of jobs){await authorize();assertRecoveryDispatch(policy,elapsed());const admission=await control.beginRecoveryContext({key:job.key});assertRecoveryDispatch(policy,admission.dispatchElapsedMs);const contextStarted=performance.now(),pkg=prepared.packages[job.role+'-'+job.mode],work=JSON.parse(await readFile(prepared.workloads[job.family+'-'+job.size].path)),contextConfig={job,...work,profilingRevision:prepared.profilingRevision,verificationRevision:prepared.verificationRevision,artifactSha256:pkg.artifactSha256,preparedSha256:binding.prepared.sha256},configPath=join(directory,job.key+'.config.json'),file=join(directory,job.key+'.json');await save(configPath,contextConfig);report.activeJob=job;await save(join(directory,'progress.json'),report);const remaining=Math.max(1,policy.perContextWatchdogMs-(performance.now()-contextStarted));let row;if(job.host==='Node-direct'){const execution=await namedNodeRun(join(pkg.directory,'node-child.mjs'),configPath,file,remaining);await save(join(directory,job.key+'.process.json'),execution);assert.equal(execution.timedOut,false,'named child watchdog; native outcome unobserved');assert.equal(execution.code,0,execution.stderr);row=JSON.parse(await readFile(file));}else row=await namedBrowserContext({browser,server,pkg,job,config:contextConfig,work,output:directory,file,timeout:remaining,preparedSha256:binding.prepared.sha256});
 row.runPolicy=policy;row.cohortIdentity=binding.cohortIdentity;row.authorizationSha256=authorization.sha256;await save(file,row);validateRecoveryRow(row,job,{artifactSha256:pkg.artifactSha256,preparedSha256:binding.prepared.sha256,identity:work.identity,profilingRevision:prepared.profilingRevision,verificationRevision:prepared.verificationRevision});await namedArtifacts(row,directory);const ended=await control.endRecoveryContext({key:job.key});report.runs.push({job,file:job.key+'.json',contextElapsedMs:ended.contextElapsedMs,dispatchElapsedMs:ended.dispatchElapsedMs,endElapsedMs:ended.endElapsedMs,outcome:row.outcome,sha256:sha(await readFile(file)),config:{file:job.key+'.config.json',sha256:sha(await readFile(configPath))},process:job.host==='Node-direct'?{file:job.key+'.process.json',sha256:sha(await readFile(join(directory,job.key+'.process.json')))}:null});report.activeJob=null;await save(join(directory,'progress.json'),report);if(policy.phase==='preflight')assert.ok(ended.contextElapsedMs<=policy.preflightGateMs,'preflight margin gate failed; remaining contexts not dispatched');}
 report.outcome='Collected';if(policy.phase==='preflight')report.launchGate='Pass';
 }catch(error){firstError=error;report.outcome='Fail';report.failure={name:error.name,message:error.message};report.interrupted=Boolean(report.activeJob);}
 finally{for(const [label,call,bound]of [['browser connection close',()=>browser?.close(),3000],['browser server close',()=>browserServer?.close(),3000],['local server close',()=>server?new Promise(yes=>server.close(yes)):undefined,3000]])try{await stageBound(call,closingBound(bound),label);}catch(error){(report.closingFailures??=[]).push({stage:label,name:error.name,message:error.message});firstError??=error;report.outcome='Fail';}
 try{await stageBound(async()=>{await authorize();const current=await readNamedPreparation(binding.prepared.path);assert.deepEqual(namedBinding(current,binding.output,binding.preflight),binding);},closingBound(60000),'final guards');report.guards='Pass';}catch(error){report.guards='Fail';report.guardFailure=error.message;firstError??=error;report.outcome='Fail';}
 report.finishedAt=new Date().toISOString();report.elapsedMs=elapsed();if(report.elapsedMs>policy.budgetMs){report.outcome='Fail';report.budgetExceeded=true;firstError??=Error('Named inner total bound exceeded');}if(report.outcome==='Collected'){try{const {jobs,rows}=await stageBound(()=>namedRows(report,directory,sealed.prepared),closingBound(60000),'final artifact validation');report.elapsedMs=elapsed();report.coverage=validateRecoveryPolicyReport(report,{policy,jobs,binding,rows,validateRow:(row,job)=>validateRecoveryRow(row,job)});}catch(error){firstError??=error;report.outcome='Fail';report.failure??={name:error.name,message:error.message};}}
 report.finishedAt=new Date().toISOString();report.elapsedMs=elapsed();if(report.elapsedMs>policy.budgetMs){report.outcome='Fail';report.budgetExceeded=true;firstError??=Error('Named inner validation exceeded total bound');}await stageBound(()=>save(join(directory,'report.json'),report),closingBound(5000),'terminal report');}
 if(firstError)throw firstError;return report;
}
async function main(){const{command,options}=parseRecoveryArguments(process.argv.slice(2));if(command==='prepare')await prepareRecovery(options);else if(command==='collect')await collectRecovery({...options,indices:options.jobs?.split(',').map(Number)});else if(command==='collect-named')await collectNamedRecovery(options);}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))await main();
